# Benchmark R mirt wall time on the identical CSV datasets generated by benchmarks/data.py.
#
# For each case, runs two mirt algorithm configurations with TOL = 1e-4 and 61 quadrature points
# on [-6, 6] (with theta_lim passed inside `technical`, matching DESIGN.md §9 and VALIDATION.md):
#   1. "default": mirt's default acceleration ("Ramsay") and default optimizer.
#   2. "nr_none": validation settings (optimizer = "NR", accelerate = "none").
# Each configuration is timed with SE = FALSE and SE = TRUE (SE.type = "Oakes"), reporting the
# median elapsed time of 3 repeated runs via system.time() (1 run in --quick mode).
#
# Run from the repository root:
#   Rscript benchmarks/run_mirt.R
#   Rscript benchmarks/run_mirt.R --quick

suppressMessages({
  library(mirt)
  library(jsonlite)
})

parse_args <- function(args) {
  cfg <- list(
    data_dir = file.path("benchmarks", "data"),
    out = file.path("benchmarks", "data", "mirt_raw.json"),
    cases = character(0),
    quick = FALSE,
    repeats = NA_integer_,
    tol = 1e-4,
    ncycles = 2000L,
    quadpts = 61L,
    theta_lim = c(-6, 6)
  )
  i <- 1L
  while (i <= length(args)) {
    flag <- args[i]
    if (flag == "--data-dir") {
      cfg$data_dir <- args[i + 1L]; i <- i + 2L
    } else if (flag == "--out") {
      cfg$out <- args[i + 1L]; i <- i + 2L
    } else if (flag == "--quick") {
      cfg$quick <- TRUE; i <- i + 1L
    } else if (flag == "--repeats") {
      cfg$repeats <- as.integer(args[i + 1L]); i <- i + 2L
    } else if (flag == "--tol") {
      cfg$tol <- as.numeric(args[i + 1L]); i <- i + 2L
    } else if (flag == "--ncycles") {
      cfg$ncycles <- as.integer(args[i + 1L]); i <- i + 2L
    } else if (flag == "--cases") {
      i <- i + 1L
      vals <- character(0)
      while (i <= length(args) && !startsWith(args[i], "--")) {
        vals <- c(vals, args[i]); i <- i + 1L
      }
      cfg$cases <- vals
    } else {
      stop(paste("Unknown argument:", flag))
    }
  }
  if (is.na(cfg$repeats)) {
    cfg$repeats <- if (cfg$quick) 1L else 3L
  }
  cfg
}

cfg <- parse_args(commandArgs(trailingOnly = TRUE))

manifest_path <- file.path(cfg$data_dir, "manifest.json")
if (!file.exists(manifest_path)) {
  stop("manifest.json not found in ", cfg$data_dir, ". Run `uv run python benchmarks/data.py` first.")
}
manifest <- fromJSON(manifest_path, simplifyDataFrame = FALSE)
all_cases <- manifest$cases

quick_names <- c("2pl_n1000_j20", "grm4_n2000_j20")
if (length(cfg$cases) > 0L) {
  selected <- Filter(function(c) c$name %in% cfg$cases, all_cases)
  if (length(selected) != length(cfg$cases)) {
    found <- vapply(selected, `[[`, character(1), "name")
    stop("Unknown case(s): ", paste(setdiff(cfg$cases, found), collapse = ", "))
  }
} else if (cfg$quick) {
  selected <- Filter(function(c) c$name %in% quick_names, all_cases)
} else {
  selected <- all_cases
}

fit_once <- function(case_info, dat, grp, algo, se_flag) {
  # NOTE: theta_lim MUST be inside `technical` for mirt() / multipleGroup(); top-level theta_lim
  # is silently ignored.
  tech <- list(NCYCLES = cfg$ncycles, theta_lim = cfg$theta_lim)
  common <- list(
    TOL = cfg$tol,
    quadpts = cfg$quadpts,
    technical = tech,
    SE = se_flag,
    verbose = FALSE
  )
  if (se_flag) {
    common$SE.type <- "Oakes"
  }
  if (algo == "nr_none") {
    common$optimizer <- "NR"
    common$accelerate <- "none"
  }

  model_kind <- case_info$model
  warns <- character(0)
  m <- NULL
  elapsed <- system.time({
    m <- withCallingHandlers(
      {
        if (model_kind == "2pl") {
          do.call(mirt, c(list(dat, 1, itemtype = "2PL"), common))
        } else if (model_kind == "grm") {
          do.call(mirt, c(list(dat, 1, itemtype = "graded"), common))
        } else if (model_kind == "3pl") {
          do.call(mirt, c(list(dat, 1, itemtype = "3PL"), common))
        } else if (model_kind == "twogroup_2pl") {
          anchors <- unlist(case_info$anchors)
          do.call(
            multipleGroup,
            c(
              list(
                dat,
                1,
                group = grp,
                itemtype = "2PL",
                invariance = c(anchors, "free_means", "free_var")
              ),
              common
            )
          )
        } else {
          stop("Unsupported model: ", model_kind)
        }
      },
      warning = function(w) {
        warns <<- c(warns, conditionMessage(w))
        invokeRestart("muffleWarning")
      }
    )
  })[["elapsed"]]

  grid_range <- range(m@Model$Theta)
  grid_n <- nrow(m@Model$Theta)
  stopifnot(
    grid_n == cfg$quadpts,
    all(abs(grid_range - cfg$theta_lim) < 1e-12)
  )

  list(
    elapsed_s = unname(as.numeric(elapsed)),
    iterations = as.integer(extract.mirt(m, "iterations")),
    converged = isTRUE(extract.mirt(m, "converged")),
    loglik = as.numeric(extract.mirt(m, "logLik")),
    grid_check = as.numeric(grid_range),
    quadpts_check = as.integer(grid_n),
    optimizer_used = as.character(m@Options$Moptim),
    accelerate_used = as.character(m@Options$accelerate),
    warnings = unique(warns)
  )
}

runs <- list()
idx <- 1L

for (case_info in selected) {
  csv_path <- file.path(cfg$data_dir, case_info$csv)
  raw_df <- read.csv(csv_path, stringsAsFactors = FALSE)
  if (case_info$n_groups > 1L) {
    grp <- factor(raw_df$group, levels = unlist(case_info$groups))
    dat <- raw_df[, setdiff(colnames(raw_df), "group"), drop = FALSE]
  } else {
    grp <- NULL
    dat <- raw_df
  }

  for (se_name in c("none", "oakes")) {
    se_flag <- (se_name == "oakes")
    for (algo in c("default", "nr_none")) {
      elapsed_vec <- numeric(cfg$repeats)
      last <- NULL
      for (r in seq_len(cfg$repeats)) {
        last <- fit_once(case_info, dat, grp, algo, se_flag)
        elapsed_vec[r] <- last$elapsed_s
      }
      rec <- list(
        case = case_info$name,
        algo = algo,
        se = se_name,
        elapsed_s = unname(median(elapsed_vec)),
        min_s = unname(min(elapsed_vec)),
        max_s = unname(max(elapsed_vec)),
        runs_s = unname(as.list(elapsed_vec)),
        iterations = last$iterations,
        converged = last$converged,
        loglik = last$loglik,
        grid_check = last$grid_check,
        quadpts_check = last$quadpts_check,
        optimizer_used = last$optimizer_used,
        accelerate_used = last$accelerate_used,
        warnings = as.list(last$warnings)
      )
      runs[[idx]] <- rec
      idx <- idx + 1L
      warn_tag <- if (length(last$warnings) > 0L) {
        sprintf(" [warnings=%d]", length(last$warnings))
      } else {
        ""
      }
      cat(sprintf(
        "%-24s se=%-5s %-7s median=%6.3fs iter=%4d ll=%.4f conv=%s (opt=%s, acc=%s)%s\n",
        case_info$name,
        se_name,
        algo,
        rec$elapsed_s,
        rec$iterations,
        rec$loglik,
        rec$converged,
        rec$optimizer_used,
        rec$accelerate_used,
        warn_tag
      ))
      flush.console()
    }
  }
}

payload <- list(
  meta = list(
    date = format(Sys.Date(), "%Y-%m-%d"),
    r_version = R.version.string,
    mirt_version = as.character(packageVersion("mirt")),
    platform = R.version$platform,
    settings = list(
      tol = cfg$tol,
      ncycles = cfg$ncycles,
      quadpts = cfg$quadpts,
      theta_lim = cfg$theta_lim,
      repeats = cfg$repeats,
      quick = cfg$quick
    )
  ),
  runs = runs
)

dir.create(dirname(cfg$out), showWarnings = FALSE, recursive = TRUE)
write_json(payload, cfg$out, auto_unbox = TRUE, digits = NA, pretty = TRUE)
cat("wrote", cfg$out, "\n")
